package cn.labmanage.admin;

import cn.labmanage.common.ApiResult;
import cn.labmanage.auth.CampusIdentityRules;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
import java.util.Map;
import org.springframework.transaction.annotation.Transactional;

@RestController @RequestMapping("/api/admin")
public class AdminController {
    private static final java.util.Set<String> ROLES=java.util.Set.of("USER","LAB_ADMIN","SYS_ADMIN","READ_ONLY_ADMIN");
    private final JdbcTemplate db;
    public AdminController(JdbcTemplate db) { this.db=db; }
    @GetMapping("/users") @PreAuthorize("hasAnyRole('SYS_ADMIN','READ_ONLY_ADMIN')") public ApiResult<?> users() { return ApiResult.ok(db.queryForList("SELECT u.id,u.username,u.real_name realName,u.email,u.phone,u.enabled,ci.identity_no identityNo,ci.person_type personType,r.code role FROM lab_user u JOIN user_role ur ON ur.user_id=u.id JOIN role r ON r.id=ur.role_id LEFT JOIN campus_identity ci ON ci.id=u.identity_id ORDER BY u.id")); }
    @GetMapping("/identities") @PreAuthorize("hasAnyRole('SYS_ADMIN','READ_ONLY_ADMIN')") public ApiResult<?> identities() { return ApiResult.ok(db.queryForList("SELECT ci.id,ci.identity_no identityNo,ci.real_name realName,ci.person_type personType,ci.default_role_code role,ci.active,u.username FROM campus_identity ci LEFT JOIN lab_user u ON u.identity_id=ci.id ORDER BY ci.identity_no")); }
    @PostMapping("/identities") @PreAuthorize("hasRole('SYS_ADMIN')") public ApiResult<?> createIdentity(@RequestBody Map<String,Object> in) { String identityNo=String.valueOf(in.getOrDefault("identityNo","")),realName=String.valueOf(in.getOrDefault("realName","")),personType=String.valueOf(in.getOrDefault("personType","")),role=String.valueOf(in.getOrDefault("role","")); validateIdentity(identityNo,realName,personType,role); db.update("INSERT INTO campus_identity(identity_no,real_name,person_type,default_role_code) VALUES(?,?,?,?)",identityNo,realName,personType,role); return ApiResult.ok(Map.of("created",true)); }
    @PutMapping("/identities/{id}") @PreAuthorize("hasRole('SYS_ADMIN')") public ApiResult<?> updateIdentity(@PathVariable long id,@RequestBody Map<String,Object> in) { Integer bound=db.queryForObject("SELECT COUNT(*) FROM lab_user WHERE identity_id=?",Integer.class,id); if(bound!=null&&bound>0) { db.update("UPDATE campus_identity SET active=? WHERE id=?",Boolean.TRUE.equals(in.get("active")),id); return ApiResult.ok(Map.of("updated",true,"identityLocked",true)); } String identityNo=String.valueOf(in.getOrDefault("identityNo","")),realName=String.valueOf(in.getOrDefault("realName","")),personType=String.valueOf(in.getOrDefault("personType","")),role=String.valueOf(in.getOrDefault("role","")); validateIdentity(identityNo,realName,personType,role); db.update("UPDATE campus_identity SET identity_no=?,real_name=?,person_type=?,default_role_code=?,active=? WHERE id=?",identityNo,realName,personType,role,Boolean.TRUE.equals(in.get("active")),id); return ApiResult.ok(Map.of("updated",true)); }
    private void validateIdentity(String identityNo,String realName,String personType,String role) { if(realName.isBlank()||!java.util.Set.of("STUDENT","STAFF").contains(personType)||!ROLES.contains(role)||("STUDENT".equals(personType)&&!"USER".equals(role))) throw new cn.labmanage.common.BusinessException("请填写有效的校园身份信息"); if(!CampusIdentityRules.isValid(identityNo,personType)) throw new cn.labmanage.common.BusinessException(CampusIdentityRules.message(personType)); }
    @PostMapping("/users") @PreAuthorize("hasRole('SYS_ADMIN')") @Transactional public ApiResult<?> user(@RequestBody Map<String,String> in,org.springframework.security.crypto.password.PasswordEncoder encoder) {
        String username=in.get("username"), identityNo=in.get("identityNo"), email=in.get("email"), phone=in.get("phone"), password=in.get("password"), role=in.get("role");
        if(username==null||username.isBlank()||identityNo==null||identityNo.isBlank()||email==null||!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||phone==null||phone.isBlank()||password==null||password.length()<8) throw new cn.labmanage.common.BusinessException("请填写有效账号、身份编号、邮箱、电话和至少8位密码");
        var identities=db.queryForList("SELECT ci.id,ci.real_name,ci.default_role_code FROM campus_identity ci LEFT JOIN lab_user u ON u.identity_id=ci.id WHERE ci.identity_no=? AND ci.active=1 AND u.id IS NULL",identityNo); if(identities.isEmpty()) throw new cn.labmanage.common.BusinessException("学号或工号不存在或已注册");
        String expected=(String)identities.get(0).get("default_role_code"); if(role!=null&&!role.equals(expected)) throw new cn.labmanage.common.BusinessException("用户角色必须与预登记校园身份一致");
        db.update("INSERT INTO lab_user(username,password_hash,real_name,email,phone,identity_id) VALUES(?,?,?,?,?,?)",username,encoder.encode(password),identities.get(0).get("real_name"),email,phone,identities.get(0).get("id"));
        Long id=db.queryForObject("SELECT LAST_INSERT_ID()",Long.class); db.update("INSERT INTO user_role SELECT ?,id FROM role WHERE code=?",id,expected); return ApiResult.ok(Map.of("created",true));
    }
    @PutMapping("/users/{id}") @PreAuthorize("hasRole('SYS_ADMIN')") @Transactional public ApiResult<?> updateUser(@PathVariable long id,@RequestBody Map<String,Object> in,org.springframework.security.core.Authentication auth) { Long self=db.queryForObject("SELECT id FROM lab_user WHERE username=?",Long.class,auth.getName()); String currentRole=db.queryForObject("SELECT r.code FROM user_role ur JOIN role r ON r.id=ur.role_id WHERE ur.user_id=?",String.class,id); if(self==id&&!java.util.Objects.equals(currentRole,in.get("role"))) throw new cn.labmanage.common.BusinessException("系统管理员不能修改自己的权限"); String role=String.valueOf(in.get("role")); Integer matching=db.queryForObject("SELECT COUNT(*) FROM lab_user u JOIN campus_identity ci ON ci.id=u.identity_id WHERE u.id=? AND ci.default_role_code=?",Integer.class,id,role); if(matching==null||matching==0) throw new cn.labmanage.common.BusinessException("用户角色不能脱离预登记校园身份"); db.update("UPDATE lab_user SET email=?,phone=?,enabled=? WHERE id=?",in.get("email"),in.get("phone"),Boolean.TRUE.equals(in.get("enabled")),id); return ApiResult.ok(Map.of("updated",true)); }
    @PostMapping("/labs") @PreAuthorize("hasRole('SYS_ADMIN')") public ApiResult<?> lab(@RequestBody Map<String,String> in) { db.update("INSERT INTO laboratory(name,location) VALUES(?,?)",in.get("name"),in.get("location")); return ApiResult.ok(Map.of("created",true)); }
    @PostMapping("/categories") @PreAuthorize("hasRole('SYS_ADMIN')") public ApiResult<?> category(@RequestBody Map<String,String> in) { db.update("INSERT INTO equipment_category(name,description) VALUES(?,?)",in.get("name"),in.get("description")); return ApiResult.ok(Map.of("created",true)); }
    @PutMapping("/labs/{id}") @PreAuthorize("hasRole('SYS_ADMIN')") public ApiResult<?> updateLab(@PathVariable long id,@RequestBody Map<String,String> in) { db.update("UPDATE laboratory SET name=?,location=? WHERE id=?",in.get("name"),in.get("location"),id); return ApiResult.ok(Map.of("updated",true)); }
    @PutMapping("/categories/{id}") @PreAuthorize("hasRole('SYS_ADMIN')") public ApiResult<?> updateCategory(@PathVariable long id,@RequestBody Map<String,String> in) { db.update("UPDATE equipment_category SET name=?,description=? WHERE id=?",in.get("name"),in.get("description"),id); return ApiResult.ok(Map.of("updated",true)); }
}
